import json

todo_id = params["todo_id"]

if not todo_id:
    result = "no_todo_id"
else:
    item = api.workq.get(todo_id=todo_id)
    if not item:
        result = "not_found"
    else:
        labels = item.get("labels") or []
        if "payroll-correction" not in labels:
            result = "not_a_correction_item"
        else:
            description = str(item.get("description") or "")
            marker = "\n---CORRECTION-DATA---\n"
            if marker not in description:
                result = "no_correction_data"
            else:
                human_text, _, raw_json = description.partition(marker)
                try:
                    data = json.loads(raw_json)
                except Exception:
                    data = {}
                policy = str(data.get("policy") or "")
                employee_name = str(data.get("employee_name") or "")
                pay_run_period = str(data.get("pay_run_period") or "")
                segments = data.get("segments") or []

                if policy == "revert":
                    note = "Marked done -- this was a revert-policy correction, which has no automated step. No further action from this automation."
                elif policy in ("next_pay_run", "unscheduled_pay_run"):
                    target = "the next DRAFT pay run" if policy == "next_pay_run" else "a new unscheduled pay run"
                    adjustment_lines = []
                    for s in segments:
                        variance = s.get("variance") or 0
                        direction = "was overpaid" if variance > 0 else "was underpaid"
                        adjustment_lines.append(f"- {s.get('name')}: adjust by {-variance}h ({direction} {abs(variance)}h)")
                    note = (
                        f"Approved. This automation can't yet write directly to a Xero payslip (that capability "
                        f"isn't built), so apply this manually in {target} for {employee_name} "
                        f"(pay run period: {pay_run_period}):\n" + "\n".join(adjustment_lines) +
                        "\n\nOnce applied in Xero, no further action is needed here."
                    )
                else:
                    note = "Marked done, but this item's policy couldn't be recognized -- please review manually."

                api.workq.update(todo_id=todo_id, description=description + "\n\n[Corrections Workflow: Execute]: " + note)
                result = "handled"
